156  void ComprDataIO::UnpWrite(byte *Addr,size_t Count)
   157  {
   158
   159  #ifdef RARDLL
   160    RAROptions *Cmd=((Archive *)SrcFile)->GetRAROptions();
   161    if (Cmd->DllOpMode!=RAR_SKIP)
   162    {
   163      if (Cmd->Callback!=NULL &&
   164          Cmd->Callback(UCM_PROCESSDATA,Cmd->UserData,(LPARAM)Addr,Count)==-1)
   165        ErrHandler.Exit(RARX_USERBREAK);
   166      if (Cmd->ProcessDataProc!=NULL)
   167      {
   168        // Here we preserve ESP value. It is necessary for those developers,
   169        // who still define ProcessDataProc callback as "C" type function,
   170        // even though in year 2001 we announced in unrar.dll whatsnew.txt
   171        // that it will be PASCAL type (for compatibility with Visual Basic).
   172  #if defined(_MSC_VER)
   173  #ifndef _WIN_64
   174        __asm mov ebx,esp
   175  #endif
   176  #elif defined(_WIN_ALL) && defined(__BORLANDC__)
   177        _EBX=_ESP;
   178  #endif
   179        int RetCode=Cmd->ProcessDataProc(Addr,(int)Count);
   180
   181        // Restore ESP after ProcessDataProc with wrongly defined calling
   182        // convention broken it.
   183  #if defined(_MSC_VER)
   184  #ifndef _WIN_64
   185        __asm mov esp,ebx
   186  #endif
   187  #elif defined(_WIN_ALL) && defined(__BORLANDC__)
   188        _ESP=_EBX;
   189  #endif
   190        if (RetCode==0)
   191          ErrHandler.Exit(RARX_USERBREAK);
   192      }
   193    }
   194  #endif // RARDLL
   195
   196    UnpWrAddr=Addr;
   197    UnpWrSize=Count;
   198    if (UnpackToMemory)
   199    {
   200      if (Count <= UnpackToMemorySize)
   201      {
   202        memcpy(UnpackToMemoryAddr,Addr,Count);
   203        UnpackToMemoryAddr+=Count;
   204        UnpackToMemorySize-=Count;
   205      }
   206    }
   207    else
   208      if (!TestMode)
   209        DestFile->Write(Addr,Count);
   210    CurUnpWrite+=Count;
   211    if (!SkipUnpCRC)
   212      UnpHash.Update(Addr,Count);
   213    ShowUnpWrite();
   214    Wait();
