   782  void CmdExtract::UnstoreFile(ComprDataIO &DataIO,int64 DestUnpSize)
   783  {
   784    Array<byte> Buffer(File::CopyBufferSize());
   785    while (1)
   786    {
   787      uint Code=DataIO.UnpRead(&Buffer[0],Buffer.Size());
   788      if (Code==0 || (int)Code==-1)
   789        break;
   790      Code=Code<DestUnpSize ? Code:(uint)DestUnpSize;
   791      DataIO.UnpWrite(&Buffer[0],Code);
   792      if (DestUnpSize>=0)
   793        DestUnpSize-=Code;
   794    }
